import type { CSSProperties } from 'react';
import { MOODS } from '../../data';
import type { Flavor, Mood } from '../../types';
import JellyBean from '../../components/JellyBean';

interface Props {
  mode: 'flavors' | 'mood';
  /** Flavors currently loaded in the dispenser. */
  available: Flavor[];
  flavors: Flavor[];
  mood: Mood | null;
  onToggleFlavor: (f: Flavor) => void;
  onSelectMood: (m: Mood) => void;
  onBack: () => void;
  onNext: () => void;
}

/** Selection chips summarising the user's picks so far. */
export function SelectionChips({ flavors, mood }: { flavors: Flavor[]; mood: Mood | null }) {
  return (
    <ul className="chips" aria-label="Your selections">
      <li className="chip chip--flavor">{flavors[0]?.name ?? 'Select flavor 1'}</li>
      <li className="chip chip--flavor">{flavors[1]?.name ?? 'Select flavor 2'}</li>
      <li className="chip chip--mood">{mood?.name ?? 'Select a mood'}</li>
    </ul>
  );
}

/** Bubble grid for picking two flavors, then a mood. */
export default function Selector({ mode, available, flavors, mood, onToggleFlavor, onSelectMood, onBack, onNext }: Props) {
  const canNext = mode === 'flavors' ? flavors.length === 2 : mood !== null;
  const heading = mode === 'flavors' ? 'Pick two flavors' : 'Pick a mood';
  const outOfStock = mode === 'flavors' && available.length < 2;

  return (
    <section className="selector" aria-labelledby="selector-heading">
      <h1 id="selector-heading" className="selector__title">
        {heading}
      </h1>
      <SelectionChips flavors={flavors} mood={mood} />
      <p className="sr-only" aria-live="polite">
        {mode === 'flavors' ? `${flavors.length} of 2 flavors selected` : mood ? `${mood.name} selected` : ''}
      </p>

      {outOfStock && (
        <p className="selector__empty" role="status">
          The dispenser needs at least two flavors loaded. Ask a team member to refill the trays.
        </p>
      )}

      <div className="bubbles">
        {mode === 'flavors'
          ? available.map((f) => {
              const selected = flavors.some((s) => s.id === f.id);
              const disabled = !selected && flavors.length >= 2;
              return (
                <button
                  key={f.id}
                  type="button"
                  className={`bubble ${selected ? 'is-selected' : ''}`}
                  style={{ '--bubble': f.color } as CSSProperties}
                  aria-pressed={selected}
                  disabled={disabled}
                  onClick={() => onToggleFlavor(f)}
                >
                  <JellyBean color={f.color} size={52} className="bubble__bean" />
                  <span className="bubble__label">{f.name}</span>
                </button>
              );
            })
          : MOODS.map((m) => {
              const selected = mood?.id === m.id;
              return (
                <button
                  key={m.id}
                  type="button"
                  className={`bubble ${selected ? 'is-selected' : ''}`}
                  style={{ '--bubble': m.color } as CSSProperties}
                  aria-pressed={selected}
                  onClick={() => onSelectMood(m)}
                >
                  <span className="bubble__label">{m.name}</span>
                </button>
              );
            })}
      </div>

      <div className="nav-buttons">
        <button type="button" className="btn btn--outline" onClick={onBack}>
          Back
        </button>
        <button type="button" className="btn btn--primary" onClick={onNext} disabled={!canNext}>
          Next
        </button>
      </div>
    </section>
  );
}
